mapper.select:
/* PT 프로젝트 목록 조회 proposal.selectPtProjectList */ SELECT p.PT_PROJECT_ID AS PT_PROJECT_ID , p.PROJECT_NM AS PROJECT_NM , p.ORG_NM AS ORG_NM , p.TARGET_TYPE_CD AS TARGET_TYPE_CD , DATE_FORMAT(p.DUE_DT, '%Y-%m-%d') AS DUE_DT , p.STATUS_CD AS STATUS_CD , cd.CODE_NM AS STATUS_NM , DATE_FORMAT(p.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT , DATE_FORMAT(p.MODIFY_DT, '%Y-%m-%d %H:%i:%s') AS MODIFY_DT , p.CREATE_USER_ID AS CREATE_USER_ID , CASE WHEN p.WRITING_GUIDELINE_JSON IS NOT NULL THEN 'Y' ELSE 'N' END AS STAGE1_DONE_YN FROM TB_PT_PROJECT p LEFT JOIN TB_CODE cd ON cd.CODE_GRP_ID = 'PT000002' AND cd.CODE_ID = p.STATUS_CD WHERE 1 = 1
AND p.STATUS_CD = #{statusCd}
AND ( p.PROJECT_NM LIKE CONCAT('%', #{keyword}, '%') OR p.ORG_NM LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.MODIFY_DT DESC, p.CREATE_DT DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.update:
/* 채팅 로그 PT 프로젝트 참조 업데이트 proposal.updateChatLogRef */
UPDATE TB_CHAT_LOG
SET
    SVC_TY  = 'D'
    , REF_ID  = #{ptProjectId}
WHERE LOG_ID = #{logId}

/* PT 프로젝트 최대 단계 번호 업데이트 proposal.updateMaxStepNo */
UPDATE TB_PT_PROJECT
SET
    MAX_STEP_NO = GREATEST(COALESCE(MAX_STEP_NO, 0), #{maxStepNo})
    , MODIFY_DT = NOW()
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 상태 업데이트 proposal.updateProjectStatus */
UPDATE TB_PT_PROJECT
SET
    STATUS_CD  = #{statusCd}
    , MODIFY_DT = NOW()
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 작성지침 JSON 업데이트 proposal.updateProjectWritingGuideline */
UPDATE TB_PT_PROJECT
SET
    WRITING_GUIDELINE_JSON = #{writingGuidelineJson}
    , MODIFY_DT = NOW()
WHERE PT_PROJECT_ID = #{ptProjectId}

/* PT 프로젝트 제안 구분(TARGET_TYPE_CD) 업데이트 proposal.updateProjectTargetType */
UPDATE TB_PT_PROJECT
SET
    TARGET_TYPE_CD = #{targetTypeCd}
    , MODIFY_DT = NOW()
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.select:
/* PT 프로젝트 CONFIG JSON 조회 proposal.selectProjectConfigJson */
SELECT CAST(PROJECT_CONFIG_JSON AS CHAR)
FROM TB_PT_PROJECT
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.update:
/* PT 프로젝트 CONFIG JSON 업데이트 proposal.updateProjectConfigJson */
UPDATE TB_PT_PROJECT
SET
    PROJECT_CONFIG_JSON = #{projectConfigJson}
    , MODIFY_DT = NOW()
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.insert:
/* PT 파일 등록 proposal.insertPtFile */
INSERT INTO TB_PT_FILE (
    PT_FILE_ID, PT_PROJECT_ID, FILE_PURPOSE_CD,
    FILE_PATH, FILE_NM, FILE_SIZE, FILE_TYPE,
    CREATE_USER_ID, CREATE_DT
) VALUES (
    #{ptFileId}, #{ptProjectId, jdbcType=VARCHAR}, #{filePurposeCd},
    #{filePath}, #{fileNm}, #{fileSize}, #{fileType},
    #{createUserId}, NOW()
)

mapper.delete:
/* PT 요구사항 전체 삭제 proposal.deleteRequirementsByProject */
DELETE FROM TB_PT_REQUIREMENT
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.insert:
/* PT 요구사항 등록 proposal.insertRequirement */
INSERT INTO TB_PT_REQUIREMENT (
    REQUIREMENT_ID
    , PT_PROJECT_ID
    , REQ_NO
    , REQ_CATEGORY_CD
    , REQ_CONTENT
    , MANDATORY_YN
    , SOURCE_TYPE_CD
    , CONFIRM_NEEDED_YN
    , SORT_ORD
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{requirementId}
    , #{ptProjectId}
    , #{reqNo}
    , #{reqCategoryCd}
    , #{reqContent}
    , COALESCE(#{mandatoryYn}, 'Y')
    , COALESCE(#{sourceTypeCd}, '001')
    , COALESCE(#{confirmNeededYn}, 'N')
    , COALESCE(#{sortOrd}, 0)
    , #{createUserId}
    , NOW()
)

mapper.update:
/* PT 요구사항 단건 수정 proposal.updateRequirement */ UPDATE TB_PT_REQUIREMENT
REQ_NO = #{reqNo}, REQ_CATEGORY_CD = #{reqCategoryCd}, REQ_CONTENT = #{reqContent}, MANDATORY_YN = #{mandatoryYn}, SOURCE_TYPE_CD = #{sourceTypeCd}, CONFIRM_NEEDED_YN = #{confirmNeededYn}, MODIFY_DT = NOW()
WHERE REQUIREMENT_ID = #{requirementId}

mapper.delete:
/* PT 평가기준 전체 삭제 proposal.deleteEvalCriteriaByProject */
DELETE FROM TB_PT_EVAL_CRITERIA
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.insert:
/* PT 평가기준 등록 proposal.insertEvalCriteria */
INSERT INTO TB_PT_EVAL_CRITERIA (
    EVAL_CRITERIA_ID
    , PT_PROJECT_ID
    , EVAL_ITEM_NM
    , SCORE
    , EVAL_INTENT
    , HIGH_SCORE_CONDITION
    , REQUIRED_EVIDENCE
    , DIFFERENTIATION_DIRECTION
    , SLIDE_REFLECT_POSITION
    , SORT_ORD
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{evalCriteriaId}
    , #{ptProjectId}
    , #{evalItemNm}
    , COALESCE(#{score}, 0)
    , #{evalIntent}
    , #{highScoreCondition}
    , #{requiredEvidence}
    , #{differentiationDirection}
    , #{slideReflectPosition}
    , COALESCE(#{sortOrd}, 0)
    , #{createUserId}
    , NOW()
)

mapper.update:
/* PT 평가기준 단건 수정 proposal.updateEvalCriteria */ UPDATE TB_PT_EVAL_CRITERIA
EVAL_ITEM_NM = #{evalItemNm}, SCORE = #{score}, EVAL_INTENT = #{evalIntent}, HIGH_SCORE_CONDITION = #{highScoreCondition}, REQUIRED_EVIDENCE = #{requiredEvidence}, DIFFERENTIATION_DIRECTION = #{differentiationDirection}, MODIFY_DT = NOW()
WHERE EVAL_CRITERIA_ID = #{evalCriteriaId}

/* Stage2 TOC 매핑 업데이트 — LINKED_EVAL_CRITERIA_ID, COVERED_REQ_IDS_JSON, PLANNED_SLIDE_CNT 갱신 proposal.updateTocEvalLinkAndReqIds */
UPDATE TB_PT_TOC
SET LINKED_EVAL_CRITERIA_ID = #{linkedEvalCriteriaId, jdbcType=VARCHAR},
    COVERED_REQ_IDS_JSON    = #{coveredReqIdsJson, jdbcType=VARCHAR},
    PLANNED_SLIDE_CNT       = #{plannedSlideCnt}
WHERE TOC_ID = #{tocId}

/* TOC 항목 제목 수정 proposal.updateTocItem */
UPDATE TB_PT_TOC
SET SECTION_NM = #{sectionNm}
WHERE TOC_ID = #{tocId}

/* S2D: 세부 작성 지침 업데이트 proposal.updateTocGuideContent */
UPDATE TB_PT_TOC
SET GUIDE_CONTENT = #{guideContent, jdbcType=VARCHAR}
WHERE TOC_ID = #{tocId}

mapper.delete:
/* TOC 항목 단건 삭제(자식 포함) proposal.deleteTocItem */
DELETE FROM TB_PT_TOC
WHERE TOC_ID = #{tocId}
   OR PARENT_TOC_ID = #{tocId}

mapper.update:
/* TOC 항목 순서(SORT_ORD) 업데이트 proposal.updateTocSortOrd */
UPDATE TB_PT_TOC
SET SORT_ORD = #{sortOrd}
WHERE TOC_ID = #{tocId}

UPDATE TB_PT_EVAL_CRITERIA
SET SLIDE_REFLECT_POSITION = #{slideReflectPosition}, MODIFY_DT = NOW()
WHERE EVAL_CRITERIA_ID = #{evalCriteriaId}

mapper.select:
/* 프로젝트 최대 SLIDE_NO 조회 proposal.selectMaxSlideNo */
SELECT COALESCE(MAX(SLIDE_NO), 0)
FROM TB_PT_SLIDE
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.update:
/* 슬라이드 수정 proposal.updateSlide */ UPDATE TB_PT_SLIDE
LAYOUT_TYPE_CD = #{layoutType}, REQ_IDS_JSON = #{reqIdsJson}, EYEBROW_TXT = #{eyebrowTxt}, TITLE_TXT = #{titleTxt}, SUBTITLE_TXT = #{subtitleTxt}, HIGHLIGHT_BANNER_TXT = #{highlightBannerTxt}, COMPONENTS_JSON = #{componentsJson}, STEP_FLOW_BAR_JSON = #{stepFlowBarJson}, CONCLUSION_RIBBON_TXT = #{conclusionRibbonTxt}, IMAGE_GEN_HINT = #{imageGenHint}, RENDERED_IMAGE_PATH = #{renderedImagePath}, COMPOSITE_IMAGE_PATH = #{compositeImagePath}, RENDER_STATUS_CD = #{renderStatusCd}, MODIFY_DT = NOW()
WHERE SLIDE_ID = #{slideId}

mapper.select:
/* 최근 Stage4 실행 시각(분 단위) 조회 proposal.selectLatestReviewRunDt */
SELECT DATE_FORMAT(MAX(CREATE_DT), '%Y-%m-%d %H:%i')
FROM TB_PT_REVIEW
WHERE PT_PROJECT_ID = #{ptProjectId}

mapper.insert:
/* PT 출력 빌드 등록 proposal.insertExport */
INSERT INTO TB_PT_EXPORT (
    EXPORT_ID, PT_PROJECT_ID, EXPORT_TYPE_CD, BUILD_STATUS_CD, TOTAL_SLIDE_CNT,
    CREATE_USER_ID, CREATE_DT
) VALUES (
    #{exportId}, #{ptProjectId}, #{exportTypeCd}, '001', #{totalSlideCnt},
    #{createUserId, jdbcType=VARCHAR}, NOW()
)

mapper.update:
/* PT 출력 빌드 상태/결과 수정 proposal.updateExport */ UPDATE TB_PT_EXPORT
BUILD_STATUS_CD = #{buildStatusCd}, RENDERED_SLIDE_CNT = #{renderedSlideCnt}, FILE_NM = #{fileNm}, FILE_PATH = #{filePath}, FILE_SIZE = #{fileSize}, ERROR_MSG = #{errorMsg}, COMPLETE_DT = #{completeDt},
WHERE EXPORT_ID = #{exportId}

mapper.select:
/* 프로젝트 슬라이드 최신 수정일시 조회 (캐시 재사용 판단용) proposal.selectMaxSlideModifyDt */
SELECT DATE_FORMAT(MAX(MODIFY_DT), '%Y-%m-%d %H:%i:%s')
FROM TB_PT_SLIDE
WHERE PT_PROJECT_ID = #{ptProjectId}

